CHANGELOG = "## [0.255.0] - what setup downloads is said first, and every pin is held to its licence\n\n**The walker's call, 2026-10-26: releases carry no third-party package, and the user's own setup downloads them**\n(the factory's `docs/THIRD_PARTY.md`).\n\n### Added\n- **`interpreter.LICENSES`**: the licence each of the twelve downloaded packages declares in its own metadata\n  (`License-Expression`, else its licence classifier), measured in the factory's `.venv`. Ten are MIT; Pillow is\n  MIT-CMU and wrapt BSD-2-Clause.\n- **The downloads are said before anything downloads**:\n  - `interpreter.downloads()` and `downloads_said()`;\n  - printed by `setup --venv` and emitted by `prepare_environment` before pip runs;\n  - returned by `discover_installation`, and shown on the Setup tab beside Prepare environment whenever the button\n    is offered.\n\n### Changed\n- **`make_venv` refuses an environment that is not as recorded.** After pip, the environment's own interpreter\n  reports each package's installed version and declared licence (`licence_problems`). A package that is missing, at\n  another version, or declaring another licence refuses the environment and names it. Moving a pin onto a release\n  that changed its licence now fails setup instead of shipping. An interpreter that does not answer is a problem,\n  never a pass. `verify=False` is for callers that ran no install.\n\n### Tests\n- `tests/unit/test_setup_licences.py` (all 8 fail on 0.254.0):\n  - every download has a recorded licence and is said;\n  - an environment as recorded is accepted;\n  - a changed licence, a changed version or a missing package refuses it;\n  - a silent interpreter is a problem;\n  - the question reads real metadata;\n  - the factory's own `.venv`, where there is one, is as recorded (here: all twelve).\n- `tests/unit/test_setup_venv.py`'s stand-in answers the question as recorded. Its two real-environment tests, which\n  run no install, pass `verify=False`.\n- `apps/godot/tests/test_dock_downloads.gd`: the downloads are said beside the button, and only with it.\n\n"
OLD_VERSION, NEW_VERSION = '0.254.0', '0.255.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
